"""The Interest Explorer: the principled / interest-based school (interests over positions, packages of
equivalent offers, objective data). Each e-mail carries 2-3 term sheets that cost us about the same
but trade price against payment days / contract length; the supplier's next sheet shows which it values.

Learning (light): per (case, supplier) we remember the sheet we last sent; if the supplier's next sheet
moved payment days / contract length up we count a "terms" interest, if its price fell a "price" one.
The favoured kind leads the package list (terms-heavy first, or the price-led package first).

Knobs: anchor (first price cut vs their quote), step (share of the gap to their price we close per
concession), close_gap (accept when this near our package cost), patience (concede unasked when this
few moves are left).
"""

import math

from ..cost import complete_offer, must_haves_ok, snap, total_cost
from ..docs import standard_terms
from ..play import closing_move, latest, live_threads, moves_left, standing
from .rational import _first_terms, _message

FIELDS = ("payment_days", "contract_months")


class ExplorerAgent:
    def __init__(self, anchor=0.10, step=0.25, close_gap=0.01, patience=2):
        self.anchor, self.step, self.close_gap, self.patience = anchor, step, close_gap, patience
        self.state = {}  # (case_id, supplier) -> {"base", "terms", "cost", "pref": {"price", "terms"}}

    def decide(self, case, threads):
        try:
            return self._decide(case, threads)
        except Exception:  # never crash a case: close safely (must-haves + alternative), else walk away
            try:
                return closing_move(case, threads)
            except Exception:
                live = live_threads(threads) or list(threads)
                return {"supplier_id": live[0] if live else None, "message": {"action": {"type": "walk_away"}}}

    def _packages(self, case, terms, price, cost, pref):
        """2-3 term sheets at about equal cost: the price-led one at `price`, others trade price for longer terms."""
        opts, fields = case.get("term_options", {}), [f for f in FIELDS if f in case["negotiable"] and f in terms]
        longer = {f: max(opts[f]) if opts.get(f) else terms[f] + (30 if f == "payment_days" else 12) for f in fields}
        mixes = [{}, longer]  # {} = the supplier's current terms
        if len(fields) > 1 and "payment_days" in longer:
            mixes.append({"payment_days": snap(case, "payment_days", (terms["payment_days"] + longer["payment_days"]) / 2)})
        sheets = []
        target = cost({**terms, "unit_price": price})
        for mix in mixes:
            at = lambda p: complete_offer(case, {**terms, **mix, "unit_price": round(p, 2)})  # noqa: E731
            slope = cost(at(price + 1)) - cost(at(price))
            p = price + (target - cost(at(price))) / slope if slope > 0 and mix else price  # equal total cost
            sheets.append(at(min(p, terms["unit_price"])))
        sheets = [s for i, s in enumerate(sheets) if s not in sheets[:i]]
        return sheets[::-1] if pref["terms"] > pref["price"] else sheets

    def _decide(self, case, threads):
        live = live_threads(threads)
        if not live:
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        std = {s: standard_terms(threads[s]) for s in live}
        cost = lambda s, t: total_cost(case, t, std[s])  # noqa: E731
        quoting = [s for s in live if standing(threads[s])[1].get("unit_price") is not None]
        walk = {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
        if not quoting:
            return walk
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        has_alt = bool(alt.get("unit_price"))
        opening = [cost(s, _first_terms(threads[s])) for s in quoting if _first_terms(threads[s]).get("unit_price")]
        reservation = total_cost(case, alt) if has_alt else min(opening, default=math.inf)
        sid = min(quoting, key=lambda s: cost(s, standing(threads[s])[1]))
        events = threads[sid]
        sheet_id, terms = standing(events)
        compliant = must_haves_ok(case, terms, std[sid])
        beats = compliant and cost(sid, terms) < reservation
        accept = {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
        status, left = latest(events).get("status"), moves_left(case, events)
        final_ok = beats or (compliant and not has_alt)
        c = lambda t: cost(sid, t)  # noqa: E731
        theirs = terms["unit_price"]
        st = self.state.setdefault((case["case_id"], sid), {"pref": {"price": 0, "terms": 0}})
        moved = "base" in st and c(terms) < st["cost"]  # reciprocity: they improved since our last message
        if "base" in st:  # learn what they moved on
            st["pref"]["terms"] += any(terms.get(f, 0) > st["terms"].get(f, 0) for f in FIELDS)
            st["pref"]["price"] += theirs < st["terms"]["unit_price"]
        base = theirs * (1 - self.anchor) if "base" not in st else st["base"]
        reason = "Which of these terms matter most to you: price, payment timing or contract length?"
        if "base" in st:
            if moved or left <= self.patience:
                base += (theirs - base) * self.step
                reason = "Thank you for the improvement; we have moved our price closer to yours."
            else:
                reason = "We keep these packages, which are equivalent for us; please pick the one that suits you best."
        base = round(min(base, theirs), 2)
        packages = self._packages(case, terms, base, c, st["pref"])
        if status in {"agreed", "final_offer"} or left <= 0:
            if status == "final_offer" and left > 0 and final_ok:
                # their price, our terms (same rule as RationalAgent): a price-only sheet leaves our other terms at standard
                best = min(packages, key=c)
                at_theirs = {**best, "unit_price": theirs}
                if c(at_theirs) < c(terms) and must_haves_ok(case, at_theirs, std[sid]):
                    return _message(case, sid, at_theirs, "We accept your price; please confirm the terms below.")
            return accept if final_ok else walk | {"supplier_id": sid}
        if beats and c(terms) <= min(map(c, packages)) * (1 + self.close_gap):
            return accept
        st.update(base=base, terms=terms, cost=c(terms))
        msg = _message(case, sid, packages[0], reason)
        msg["message"]["term_sheets"] = [{"terms": p} for p in packages[:3]]
        return msg

"""The Rational Bargainer: the game-theory school (reservation value, outside option, time-dependent
concessions, supplier-floor estimate). Opens firm, concedes along a Boulware curve, caps itself at the
supplier's estimated floor and trades payment days for price.

Knobs: anchor (first cut below the quote), target (final discount vs the opening quote), exponent
(>1 holds firm early), margin (above the estimated floor), close_gap (accept when this near our own offer).
"""

import math

from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..play import closing_move, latest, live_threads, moves_left, standing


def _prices(events, sender):
    """Unit prices of the first term sheet in each message from the buyer (sender=True) or the supplier."""
    return [
        m["term_sheets"][0]["terms"]["unit_price"]
        for m in events
        if (m.get("from") == "buyer") == sender and m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")
    ]


def estimate_floor(prices):
    """Extrapolate the supplier's geometric concession decay to its limit; None with too little data."""
    steps = [a - b for a, b in zip(prices, prices[1:])]
    if len(steps) < 2 or steps[-1] <= 0 or steps[-2] <= 0:
        return None
    ratio = min(steps[-1] / steps[-2], 0.95)
    return prices[-1] - steps[-1] * ratio / (1 - ratio)


class RationalAgent:
    def __init__(self, anchor=0.12, target=0.03, exponent=2.0, margin=0.02, close_gap=0.01):
        self.anchor, self.target, self.exponent, self.margin, self.close_gap = anchor, target, exponent, margin, close_gap

    def decide(self, case, threads):
        try:
            return self._decide(case, threads)
        except Exception:  # never crash a case: close safely (must-haves + alternative), else walk away
            try:
                return closing_move(case, threads)
            except Exception:
                live = live_threads(threads) or list(threads)
                return {"supplier_id": live[0] if live else None, "message": {"action": {"type": "walk_away"}}}

    def _decide(self, case, threads):
        live = live_threads(threads)
        if not live:
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        std = {s: standard_terms(threads[s]) for s in live}
        cost = lambda s, t: total_cost(case, t, std[s])  # noqa: E731
        quoting = [s for s in live if standing(threads[s])[1].get("unit_price") is not None]
        walk = {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
        if not quoting:
            return walk
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        has_alt = bool(alt.get("unit_price"))
        # like with like: the alternative, else the cheapest opening sheet, both with their whole terms
        opening = [cost(s, _first_terms(threads[s])) for s in quoting if _first_terms(threads[s]).get("unit_price")]
        reservation = total_cost(case, alt) if has_alt else min(opening, default=math.inf)
        sid = min(quoting, key=lambda s: cost(s, standing(threads[s])[1]))
        events = threads[sid]
        sheet_id, terms = standing(events)
        compliant = must_haves_ok(case, terms, std[sid])
        beats = compliant and cost(sid, terms) < reservation
        accept = {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
        status, left = latest(events).get("status"), moves_left(case, events)
        # no alternative: walking away scores 0, so any compliant sheet is worth taking at the end
        final_ok = beats or (compliant and not has_alt)
        ending = status in {"agreed", "final_offer"} or left <= 0

        theirs_all, mine = _prices(events, False), _prices(events, True)
        theirs = terms["unit_price"]
        first = theirs_all[0] if theirs_all else theirs
        start = first * (1 - self.anchor)
        progress = len(mine) / max(case.get("round_limit", 10) - 1, 1)  # 0 at the first move, 1 at the last
        price = start + (first * (1 - self.target) - start) * min(progress, 1) ** self.exponent
        if (floor := estimate_floor(theirs_all)) is not None:
            price = min(price, floor * (1 + self.margin))
        price = round(min(max(price, mine[-1] if mine else 0), theirs), 2)  # never retreat, never above their price
        ask = {}
        options = case.get("term_options", {}).get("payment_days")
        if "payment_days" in case["negotiable"] and "payment_days" in terms:
            ask["payment_days"] = max(options) if options else terms["payment_days"] + 30
        offer = complete_offer(case, {**terms, **ask, "unit_price": price})
        if ending:
            if status == "final_offer" and left > 0 and final_ok:
                # their price, our terms: a price-only final sheet leaves the other terms at their standard
                # values, which can cost far more than the price step we would still win
                at_their_price = complete_offer(case, {**terms, **ask, "unit_price": theirs})
                if cost(sid, at_their_price) < cost(sid, terms) and must_haves_ok(case, at_their_price, std[sid]):
                    return _message(case, sid, at_their_price, "We accept your price; please confirm the terms below.")
            return accept if final_ok else walk | {"supplier_id": sid}
        if beats and cost(sid, terms) <= cost(sid, offer) * (1 + self.close_gap):
            return accept
        return _message(case, sid, offer, "Thank you for your offer. Based on our analysis we can offer the terms below.")


def _first_terms(events):
    sheets = next((m["term_sheets"] for m in events if m.get("from") != "buyer" and m.get("term_sheets")), None)
    return sheets[0]["terms"] if sheets else {}


def _message(case, sid, offer, body):
    return {"supplier_id": sid, "message": {"subject": case["title"], "body": body, "term_sheets": [{"terms": offer}]}}

from arena_kit.agents import ExplorerAgent
from arena_kit.cost import total_cost

from test_kit import CASE
from test_rational import _alt, _threads


def _terms(msg):
    return [s["terms"] for s in msg["term_sheets"]]


def test_sends_equivalent_packages_below_supplier_cost():
    msg = ExplorerAgent().decide(CASE, _threads([44.0]))["message"]
    sheets = _terms(msg)
    costs = [total_cost(CASE, t) for t in sheets]
    assert 2 <= len(sheets) <= 3 and len({t["payment_days"] for t in sheets}) == len(sheets)
    assert max(costs) - min(costs) <= 0.01 * min(costs)
    assert max(costs) < total_cost(CASE, {"unit_price": 44.0, "payment_days": 30})
    assert min(t["unit_price"] for t in sheets) < 44.0 * 0.95 + 0.01


def test_first_message_asks_question_without_leaking():
    msg = ExplorerAgent().decide(_alt(40.0), _threads([44.0]))["message"]
    assert "?" in msg["body"] and "alternative" not in msg["body"].lower()


def test_never_accepts_worse_than_reservation():
    case = _alt(36.0)
    msg = ExplorerAgent().decide(case, _threads([44.0, 40.0], "final_offer", [38.0]))["message"]
    assert msg["action"] == {"type": "walk_away"}


def test_accepts_agreed_better_offer():
    msg = ExplorerAgent().decide(_alt(44.0), _threads([44.0, 40.0], "agreed", [38.0]))["message"]
    assert msg["action"] == {"type": "accept", "term_sheet_id": "o1"}


def test_no_live_threads_does_not_crash():
    threads = {"sup:A": [{"from": "sup:A", "status": "walked_away", "term_sheets": []}]}
    assert ExplorerAgent().decide(CASE, threads)["message"]["action"] == {"type": "walk_away"}


def test_crash_falls_back_safely(monkeypatch):
    monkeypatch.setattr(ExplorerAgent, "_decide", lambda *a: 1 / 0)
    assert ExplorerAgent().decide(_alt(36.0), _threads([44.0, 40.0]))["message"]["action"] == {"type": "walk_away"}


def test_final_offer_counter_at_their_price():
    case = {**CASE, "buyer": {k: v for k, v in CASE["buyer"].items() if k != "alternative"}}
    msg = ExplorerAgent().decide(case, _threads([44.0, 45.0], "final_offer", [38.0]))["message"]
    assert "action" not in msg or msg["action"]["type"] == "accept"
    if "term_sheets" in msg:
        assert _terms(msg)[0]["unit_price"] == 45.0


def test_no_moves_left_worse_offer_walks_away():
    case = {**_alt(36.0), "round_limit": 1}
    msg = ExplorerAgent().decide(case, _threads([44.0, 40.0], "open", [38.0]))["message"]
    assert msg["action"] == {"type": "walk_away"}


def test_holds_packages_when_supplier_did_not_move():
    a, th = ExplorerAgent(), _threads([44.0])
    first = _terms(a.decide(CASE, th)["message"])
    th["sup:A"] += [{"from": "buyer"}, {"from": "sup:A", "status": "open", "term_sheets": [{"term_sheet_id": "o1", "terms": {"unit_price": 44.0, "payment_days": 30}}]}]
    assert _terms(a.decide(CASE, th)["message"]) == first
